//! Registry of sidecar binaries extracted from the TYNDPKG `sidecar/*` section
//! at startup. Populated by the full/lite embed loaders.
//!
//! Backed by `DashMap` — reads and writes run lock-free in the common case
//! (sharded internal mutex only on contention), so a burst of concurrent
//! `sidecar.path(name)` calls don't serialise behind one global lock.
//!
//! Dispatch is generated by `#[tynd::handler]` (U10).

use std::sync::LazyLock;

use dashmap::DashMap;
use serde_json::{json, Value};

use crate::{ipc_error::IpcError, tynd};

/// `LazyLock` (Rust 1.80+) builds the `DashMap` on first deref so
/// callers reach it via direct `SIDECARS.get(...)` instead of a
/// `registry()` accessor wrapping `OnceLock::get_or_init`.
static SIDECARS: LazyLock<DashMap<String, String>> = LazyLock::new(DashMap::new);

pub fn register(name: &str, absolute_path: &str) {
    SIDECARS.insert(name.to_string(), absolute_path.to_string());
}

/// Marker for the `#[tynd::handler]` dispatch table — sidecar state
/// lives in the file-level `SIDECARS` static.
#[derive(Debug, Default)]
pub struct SidecarApi;

#[tynd::handler(api = "sidecar")]
impl SidecarApi {
    /// Resolve the absolute path of a previously-registered sidecar
    /// binary. Errors with `sidecar '<name>' is not registered` when no
    /// matching entry was extracted from the TYNDPKG bundle.
    pub fn path(name: String) -> Result<String, String> {
        SIDECARS.get(&name).map_or_else(
            || {
                Err(IpcError::new(
                    "sidecar",
                    "path",
                    format!("sidecar '{name}' is not registered"),
                )
                .into_string())
            },
            |r| Ok(r.value().clone()),
        )
    }

    /// List every registered sidecar as `{ name, path }`. Order is
    /// arbitrary (DashMap iteration order); callers that need a stable
    /// order should sort client-side.
    pub fn list() -> Value {
        let items: Vec<Value> = SIDECARS
            .iter()
            .map(|r| json!({ "name": r.key(), "path": r.value() }))
            .collect();
        Value::Array(items)
    }
}
